begin;
create temp table checks(name text,passed boolean);
create function pg_temp.ok(v boolean,n text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',n;end if;insert into checks values(n,true);end$$;
create function pg_temp.deny(p jsonb,n text) returns void language plpgsql as $$begin begin perform public.ig_campaign_manage(p);exception when others then insert into checks values(n,true);return;end;raise exception 'FAIL: %',n;end$$;
do $$declare uid uuid;sid uuid;claims jsonb;original_roles text[];c jsonb;j jsonb;v jsonb;k text=repeat('a',64);n integer;pid text='test_campaign_provider';c2 jsonb;j2 jsonb;begin
 select u.id,s.id into uid,sid from auth.users u join auth.sessions s on s.user_id=u.id where u.email='akm@indiagully.com' order by s.created_at desc limit 1;if sid is null then raise exception 'Owner session required';end if;
 select roles into original_roles from public.ig_profiles where id=uid;
 claims=jsonb_build_object('sub',uid,'session_id',sid,'aal','aal2','role','authenticated');perform set_config('request.jwt.claims',claims::text,true);
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(k,'UTF8'),'sha256'),'hex');
 c=public.ig_campaign_manage('{"action":"save","practice":"horeca","title":"SYSTEM TEST campaign","subject":"SYSTEM TEST only","body":"Internal software verification only. No email will be sent."}');
 perform pg_temp.ok(c->>'status'='draft','Campaign starts as an unsent draft');
 insert into public.ig_consents(user_id,purpose,granted,version,practices) values(uid,'email_marketing',false,'TEST','{}');
 perform pg_temp.ok(not ig_private.campaign_eligible(uid,'horeca'),'No email without explicit opt-in');
 insert into public.ig_consents(user_id,purpose,granted,version,practices) values(uid,'email_marketing',true,'TEST',array['horeca']);
 delete from ig_private.email_suppressions where email='akm@indiagully.com';
 perform pg_temp.ok(ig_private.campaign_eligible(uid,'horeca') and not ig_private.campaign_eligible(uid,'real-estate'),'Consent matches the selected practice');
 n=(public.ig_campaign_manage(jsonb_build_object('action','preview','id',c->>'id'))->>'eligible')::integer;
 perform pg_temp.deny(jsonb_build_object('action','activate','id',c->>'id','version',1,'reviewed',true,'audience_count',n+1),'Changed audience count requires renewed review');
 update public.ig_profiles set roles=array['administrator'] where id=uid;perform pg_temp.deny(jsonb_build_object('action','activate','id',c->>'id','version',1,'reviewed',true,'audience_count',n),'Only owner may release marketing');update public.ig_profiles set roles=original_roles where id=uid;
 c=public.ig_campaign_manage(jsonb_build_object('action','activate','id',c->>'id','version',1,'reviewed',true,'audience_count',n));
 perform pg_temp.ok(c->>'status'='active' and exists(select 1 from ig_private.campaign_deliveries where campaign_id=(c->>'id')::uuid),'Approval creates a durable delivery queue');
 perform pg_temp.deny(jsonb_build_object('action','save','id',c->>'id','version',c->'version','title','Changed','subject','Changed','body','This is a changed campaign body','practice','horeca'),'Released copy cannot change behind approval');
 v=public.ig_campaign_runtime(k,'{"action":"claim"}');select x into j from jsonb_array_elements(v)x where x->>'recipient'='akm@indiagully.com';
 perform pg_temp.ok(j is not null,'Approved eligible recipient can be leased');
 v=public.ig_campaign_runtime(k,jsonb_build_object('action','prepare','id',j->>'id','lease_token',j->>'lease_token','payload','{"subject":"Frozen first payload"}'::jsonb));
 v=public.ig_campaign_runtime(k,jsonb_build_object('action','prepare','id',j->>'id','lease_token',j->>'lease_token','payload','{"subject":"Changed retry"}'::jsonb));
 perform pg_temp.ok(v->>'subject'='Frozen first payload','Retry retains exact frozen message bytes');
 perform public.ig_campaign_runtime(k,jsonb_build_object('action','event','event_id','TEST-EARLY','provider_id',pid,'event','email.delivered'));
 perform public.ig_campaign_runtime(k,jsonb_build_object('action','finish','id',j->>'id','lease_token',j->>'lease_token','provider_id',pid));
 perform pg_temp.ok(exists(select 1 from ig_private.campaign_deliveries where id=(j->>'id')::uuid and status='delivered'),'Early delivery event reconciles after provider binding');
 perform public.ig_campaign_runtime(k,jsonb_build_object('action','event','event_id','TEST-BOUNCE','provider_id',pid,'event','email.bounced'));
 perform public.ig_campaign_runtime(k,jsonb_build_object('action','event','event_id','TEST-EARLY','provider_id',pid,'event','email.delivered'));
 perform pg_temp.ok(exists(select 1 from ig_private.campaign_deliveries where id=(j->>'id')::uuid and status='suppressed') and not ig_private.campaign_eligible(uid,'horeca'),'Bounce suppression cannot be undone by replayed delivery');
 delete from ig_private.email_suppressions where email='akm@indiagully.com';
 c2=public.ig_campaign_manage('{"action":"save","practice":"horeca","title":"SYSTEM TEST follow-up","subject":"SYSTEM TEST follow-up","body":"Internal follow-up verification only. No email will be sent."}');
 n=(public.ig_campaign_manage(jsonb_build_object('action','preview','id',c2->>'id'))->>'eligible')::integer;
 c2=public.ig_campaign_manage(jsonb_build_object('action','activate','id',c2->>'id','version',1,'reviewed',true,'audience_count',n));
 v=public.ig_campaign_runtime(k,'{"action":"claim"}');perform pg_temp.ok(not exists(select 1 from jsonb_array_elements(v)x where x->>'recipient'='akm@indiagully.com'),'A second campaign is delayed inside 24 hours');
 update ig_private.campaign_deliveries set sent_at=now()-interval '2 days' where id=(j->>'id')::uuid;
 update ig_private.campaign_deliveries set next_attempt=now() where campaign_id=(c2->>'id')::uuid;
 c2=public.ig_campaign_manage(jsonb_build_object('action','pause','id',c2->>'id','version',c2->'version'));
 v=public.ig_campaign_runtime(k,'{"action":"claim"}');perform pg_temp.ok(not exists(select 1 from jsonb_array_elements(v)x where x->>'recipient'='akm@indiagully.com'),'Paused campaigns do not dispatch');
 c2=public.ig_campaign_manage(jsonb_build_object('action','resume','id',c2->>'id','version',c2->'version'));
 v=public.ig_campaign_runtime(k,'{"action":"claim"}');select x into j2 from jsonb_array_elements(v)x where x->>'recipient'='akm@indiagully.com';
 perform pg_temp.ok(j2 is not null,'Resumed eligible campaign can dispatch');
 insert into public.ig_consents(user_id,purpose,granted,version,practices) values(uid,'email_marketing',false,'TEST','{}');
 v=public.ig_campaign_runtime(k,jsonb_build_object('action','prepare','id',j2->>'id','lease_token',j2->>'lease_token','payload','{}'::jsonb));
 perform pg_temp.ok(v is null,'Withdrawal after queue claim suppresses unsent payload');
 perform public.ig_campaign_runtime(k,jsonb_build_object('action','unsubscribe','id',j->>'id'));
 perform pg_temp.ok(not ig_private.campaign_eligible(uid,'horeca'),'One-click unsubscribe records withdrawal');
 perform pg_temp.ok(not has_table_privilege('authenticated','ig_private.campaign_deliveries','select') and not has_table_privilege('authenticated','public.ig_campaigns','insert'),'Direct recipient access and campaign writes denied');
 perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);perform pg_temp.deny(jsonb_build_object('action','preview','id',c->>'id'),'Campaign controls require MFA');
end $$;
select * from checks;
rollback;
